// Row 107 — the Dart port of e2e1 must reproduce the JavaScript reference
// byte for byte (docs/cloud/contracts/e2e1-vectors-107.json, generated by
// tools/e2e1-vectors-107.mjs) and refuse exactly the same negative vectors.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:payesh_secure/payesh_secure.dart';
import 'package:test/test.dart';

Map<String, Object?> _vectors() {
  var dir = Directory.current;
  for (var i = 0; i < 6; i++) {
    final f = File('${dir.path}/docs/cloud/contracts/e2e1-vectors-107.json');
    if (f.existsSync()) {
      return jsonDecode(f.readAsStringSync()) as Map<String, Object?>;
    }
    dir = dir.parent;
  }
  throw StateError(
    'e2e1-vectors-107.json not found above ${Directory.current.path}',
  );
}

Map<String, Object?> _m(Object? o) => o as Map<String, Object?>;
List<Object?> _l(Object? o) => o as List<Object?>;
String _s(Object? o) => o as String;
int _i(Object? o) => o as int;
Uint8List _u(Object? o) => unb64u(_s(o));
Uint8List _hex(String h) => Uint8List.fromList(
  List<int>.generate(
    h.length ~/ 2,
    (i) => int.parse(h.substring(i * 2, i * 2 + 2), radix: 16),
  ),
);
String _toHex(List<int> b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

Fixed _fixed(Map<String, Object?> f) => Fixed(
  eph: _u(f['eph']),
  dek: _u(f['dek']),
  iv: _u(f['iv']),
  wrapIvs: _l(f['wrap_ivs']).map(_u).toList(),
);

RecordMeta _meta(
  Map<String, Object?> m, {
  int? recordId,
  int? version,
  String? tenant,
  String? collection,
}) => RecordMeta(
  tenantId: tenant ?? _s(m['tenant_id']),
  collection: collection ?? _s(m['collection']),
  recordId: recordId ?? _i(m['record_id']),
  version: version ?? _i(m['version']),
  classId: m['class_id'] as int?,
  studentId: m['student_id'] as int?,
);

Future<void> _refuses(Future<Object?> Function() f, String code) async {
  try {
    await f();
  } on E2EError catch (e) {
    expect(e.code, code);
    return;
  }
  fail('expected $code, but it succeeded');
}

void main() {
  final v = _vectors();
  final rec = _m(v['record']);
  final grant = _m(v['grant']);

  test('E1D-01 X25519 matches RFC 7748 §6.1', () async {
    final x = _m(v['x25519_rfc7748']);
    expect(
      _toHex(await publicFromPrivate(_hex(_s(x['alice_priv_hex'])))),
      x['alice_pub_hex'],
    );
    expect(
      _toHex(await publicFromPrivate(_hex(_s(x['bob_priv_hex'])))),
      x['bob_pub_hex'],
    );
    expect(
      _toHex(
        await x25519(_hex(_s(x['alice_priv_hex'])), _hex(_s(x['bob_pub_hex']))),
      ),
      x['shared_hex'],
    );
    expect(
      _toHex(
        await x25519(_hex(_s(x['bob_priv_hex'])), _hex(_s(x['alice_pub_hex']))),
      ),
      x['shared_hex'],
    );
  });

  test('E1D-02 scope key derivation equals the JS vectors', () async {
    for (final o in _l(v['scope_keys'])) {
      final s = _m(o);
      final k = await deriveScopeKey(
        _u(s['smk']),
        _s(s['tenant']),
        _s(s['scope']),
        _i(s['smk_gen']),
        _i(s['gen']),
      );
      expect(k.kid, s['kid']);
      expect(b64u(k.priv), s['priv'], reason: k.kid);
      expect(b64u(k.pub), s['pub'], reason: k.kid);
    }
  });

  test('E1D-03 record envelope: deterministic seal equals the JS vector; 4 readers open it', () async {
    final dir = <String, Recipient>{
      for (final o in _l(rec['recipients']))
        parseKid(_s(_m(o)['kid'])).scope: Recipient(
          _s(_m(o)['kid']),
          _u(_m(o)['pub']),
        ),
    };
    final meta = _meta(_m(rec['meta']));
    final sealed = await sealRecord(
      meta,
      _s(rec['plaintext']),
      dir,
      fixed: _fixed(_m(rec['fixed'])),
    );
    expect(sealed, rec['sealed']);
    expect(
      recordAad(meta.tenantId, meta.collection, meta.recordId, meta.version),
      rec['aad'],
    );
    for (final o in _l(rec['opens'])) {
      final key = _m(_m(o)['key']);
      final pt = await open(_s(rec['sealed']), {
        _s(key['kid']): _u(key['priv']),
      }, _s(_m(o)['aad']));
      expect(utf8.decode(pt), _m(o)['plaintext'], reason: _s(_m(o)['why']));
    }
    expect(recipientsOf(sealed).length, 4);
  });

  test(
    'E1D-04 NEGATIVE record vectors refused with the same codes as JS',
    () async {
      for (final o in _l(rec['negatives'])) {
        final n = _m(o);
        final key = _m(n['key']);
        await _refuses(
          () => open(_s(n['envelope']), {
            _s(key['kid']): _u(key['priv']),
          }, _s(n['aad'])),
          _s(n['expect']),
        );
      }
    },
  );

  test('E1D-05 grants equal the JS vectors; SMK keyring and scope keyring open the record', () async {
    final tenant = _s(grant['tenant']);
    final dev = _s(grant['device_id']);
    final devPriv = _u(grant['device_priv']);
    expect(b64u(await publicFromPrivate(devPriv)), grant['device_pub']);
    final g = await sealGrant(
      _u(grant['device_pub']),
      tenant,
      dev,
      _s(grant['kid']),
      _u(grant['secret']),
      fixed: _fixed(_m(grant['fixed'])),
    );
    expect(g, grant['sealed']);
    expect(
      b64u(await openGrant(g, devPriv, tenant, dev, _s(grant['kid']))),
      grant['secret'],
    );
    for (final o in _l(grant['negatives'])) {
      final n = _m(o);
      await _refuses(
        () => openGrant(
          _s(n['envelope']),
          devPriv,
          tenant,
          _s(n['device_id']),
          _s(n['kid']),
        ),
        _s(n['expect']),
      );
    }
    final sg = _m(grant['smk_grant']);
    final sgSealed = await sealGrant(
      _u(grant['device_pub']),
      tenant,
      dev,
      _s(sg['kid']),
      _u(sg['secret']),
      fixed: _fixed(_m(sg['fixed'])),
    );
    expect(sgSealed, sg['sealed']);
    final manager = Keyring(tenant);
    await manager.addGrant(
      _s(sg['kid']),
      await openGrant(sgSealed, devPriv, tenant, dev, _s(sg['kid'])),
    );
    final meta = _meta(_m(rec['meta']));
    expect(
      await manager.openRecordText(meta, _s(rec['sealed'])),
      rec['plaintext'],
    );
    final teacher = Keyring(tenant);
    await teacher.addGrant(_s(grant['kid']), _u(grant['secret']));
    expect(
      await teacher.openRecordText(meta, _s(rec['sealed'])),
      rec['plaintext'],
    );
    await _refuses(
      () => teacher.openRecordText(
        _meta(_m(rec['meta']), recordId: 9002),
        _s(rec['sealed']),
      ),
      'e2e_open_failed',
    );
  });

  test('E1D-06 random sealing round-trips (Persian text, 64 KiB) and is non-deterministic', () async {
    final smk = Uint8List.fromList(List<int>.generate(32, (i) => i));
    final k = await deriveScopeKey(
      smk,
      _s(grant['tenant']),
      'school:notes',
      1,
      0,
    );
    final aad = recordAad(_s(grant['tenant']), 'notes', 1, 1);
    final a = await seal([k], utf8.encode('یادداشت مشاور'), aad);
    final b = await seal([k], utf8.encode('یادداشت مشاور'), aad);
    expect(a == b, isFalse);
    expect(utf8.decode(await open(a, {k.kid: k.priv}, aad)), 'یادداشت مشاور');
    final big = Uint8List(65536)..fillRange(0, 65536, 0x61);
    expect(await open(await seal([k], big, aad), {k.kid: k.priv}, aad), big);
  });

  test('E1D-07 NEGATIVE malformed input fails closed', () async {
    final s = _s(rec['sealed']);
    final p = s.split('.');
    await _refuses(
      () => x25519(Uint8List(32)..[0] = 1, Uint8List(32)),
      'e2e_bad_key',
    );
    await _refuses(
      () async => recipientsOf([p[0], '${p[1]}A', p[2], p[3], p[4]].join('.')),
      'e2e_bad_format',
    );
    await _refuses(
      () async => recipientsOf('e2e2${s.substring(4)}'),
      'e2e_bad_format',
    );
    await _refuses(() async => recipientsOf('$s.x'), 'e2e_bad_format');
    await _refuses(
      () async =>
          recipientsOf([p[0], p[1], p[2], p[3], 'device!x!y'].join('.')),
      'e2e_bad_format',
    );
    await _refuses(() async => unb64u('A'), 'e2e_bad_format');
    await _refuses(() async => unb64u('AB'), 'e2e_bad_format');
    await _refuses(() async => unb64u('a+b/'), 'e2e_bad_format');
    await _refuses(
      () async => recordAad(_s(grant['tenant']), 'Attendance', 1, 1),
      'e2e_bad_record',
    );
    await _refuses(
      () async => kidOf('class:7:attendance', 0, 0),
      'e2e_bad_scope',
    );
    await _refuses(() async => parseKid('device'), 'e2e_bad_scope');
    await _refuses(() async => scopeName('room', 'x', 1), 'e2e_bad_scope');
    await _refuses(() async => scopeName('class', 'Bad', 1), 'e2e_bad_scope');
    await _refuses(() => seal(const [], [1], 'a'), 'e2e_no_recipient');
    final k = await deriveScopeKey(
      Uint8List(32),
      _s(grant['tenant']),
      'school:x',
      1,
      0,
    );
    await _refuses(() => seal([k, k], [1], 'a'), 'e2e_bad_scope');
    await _refuses(() => open(s, const {}, _s(rec['aad'])), 'e2e_no_key');
    await _refuses(() => publicFromPrivate(Uint8List(31)), 'e2e_bad_key');
    await _refuses(
      () => sealGrant(Uint8List(32), 't', 'd', 'smk@1+0', Uint8List(16)),
      'e2e_bad_key',
    );
    await _refuses(
      () => sealRecord(_meta(_m(rec['meta'])), '{}', {'school:attendance': k}),
      'e2e_no_scope_key',
    );
    final only = await sealRecord(_meta(_m(rec['meta'])), '{}', {'smk': k});
    expect(recipientsOf(only), [k.kid]);
    expect(E2EError('e2e_bad_key', 'x').toString(), 'e2e_bad_key: x');
    expect(E2EError('e2e_no_key').toString(), 'e2e_no_key');
  });

  test('E1D-08 rotation: the old class generation cannot open a row re-sealed to gen+1', () async {
    final tenant = _s(grant['tenant']);
    final smk = _u(_m(_l(v['scope_keys']).first)['smk']);
    const meta = RecordMeta(
      tenantId: '0b7e6a52-3f0c-4c1e-9a55-2f1d7c0e9a01',
      collection: 'attendance',
      recordId: 77,
      version: 2,
      classId: 7,
    );
    final old = await deriveScopeKey(smk, tenant, 'class:7:attendance', 1, 0);
    final dir = <String, Recipient>{
      'smk': await deriveScopeKey(smk, tenant, 'smk', 1, 0),
      'school:attendance': await deriveScopeKey(
        smk,
        tenant,
        'school:attendance',
        1,
        0,
      ),
      'class:7:attendance': await deriveScopeKey(
        smk,
        tenant,
        'class:7:attendance',
        1,
        1,
      ),
    };
    final sealed = await sealRecord(meta, '{"s":"present"}', dir);
    await _refuses(
      () => openRecord(meta, sealed, {old.kid: old.priv}),
      'e2e_no_key',
    );
    await _refuses(
      () => openRecord(meta, sealed, {'class:7:attendance@1+1': old.priv}),
      'e2e_open_failed',
    );
    final ring = Keyring(tenant);
    await ring.addGrant('smk@1+0', smk);
    expect(await ring.openRecordText(meta, sealed), '{"s":"present"}');
  });
}
